CREATE TABLE public.districts (id text PRIMARY KEY, slug text UNIQUE NOT NULL, name_en text NOT NULL, name_ur text NOT NULL, name_ps text, lat double precision NOT NULL, lng double precision NOT NULL, region text, is_ardc boolean);
GRANT SELECT ON public.districts TO anon, authenticated;
GRANT ALL ON public.districts TO service_role;
ALTER TABLE public.districts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public district references" ON public.districts FOR SELECT TO anon, authenticated USING (true);
ALTER TABLE public.monitoring_snapshots ADD COLUMN id uuid NOT NULL DEFAULT gen_random_uuid(), ADD COLUMN district_id text;
INSERT INTO public.districts (id,slug,name_en,name_ur,lat,lng) SELECT district,district,district,district,0,0 FROM public.monitoring_snapshots ON CONFLICT (id) DO NOTHING;
UPDATE public.monitoring_snapshots SET district_id=district WHERE district_id IS NULL;
ALTER TABLE public.monitoring_snapshots ADD CONSTRAINT monitoring_snapshot_district_ref FOREIGN KEY (district_id) REFERENCES public.districts(id);
CREATE UNIQUE INDEX monitoring_snapshot_district_id ON public.monitoring_snapshots(district_id);
CREATE TABLE public.monitoring_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text NOT NULL DEFAULT 'running', http_status jsonb NOT NULL DEFAULT '{}'::jsonb, districts_ok integer NOT NULL DEFAULT 0, districts_failed integer NOT NULL DEFAULT 0, error_text text);
GRANT SELECT ON public.monitoring_runs TO anon, authenticated;
GRANT ALL ON public.monitoring_runs TO service_role;
ALTER TABLE public.monitoring_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public monitoring run status" ON public.monitoring_runs FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.service_health (service text PRIMARY KEY, last_success_at timestamptz, last_error_at timestamptz, last_error_text text);
GRANT SELECT ON public.service_health TO anon, authenticated;
GRANT ALL ON public.service_health TO service_role;
ALTER TABLE public.service_health ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public environmental service health" ON public.service_health FOR SELECT TO anon, authenticated USING (true);